begin;
create table if not exists public.facility_visit_authorizations(id uuid primary key,tenant_id uuid not null,facility_id uuid not null,company_id uuid not null,representative_id uuid not null,visit_date bigint not null,shift text not null,status text not null default 'AUTHORIZED',created_at bigint not null,updated_at bigint not null);
create table if not exists public.entry_permits(id uuid primary key,tenant_id uuid not null,facility_id uuid not null,company_id uuid not null,representative_id uuid not null,permit_number text not null,qr_code text not null,visit_date bigint not null,shift text not null,issued_by_employee_id uuid not null,printed_at bigint not null,status text not null default 'ACTIVE',unique(tenant_id,permit_number));
create table if not exists public.employees(id uuid primary key,tenant_id uuid not null,username text not null,name text not null,role text not null check(role in('FACILITY_ADMIN','RECEPTIONIST','VIEWER')),active boolean not null default true,created_at bigint not null,updated_at bigint not null,unique(tenant_id,username));
create index if not exists idx_fva_tenant on public.facility_visit_authorizations(tenant_id);create index if not exists idx_permits_tenant on public.entry_permits(tenant_id);create index if not exists idx_employees_tenant on public.employees(tenant_id);
alter table public.facility_visit_authorizations enable row level security;alter table public.entry_permits enable row level security;alter table public.employees enable row level security;
drop policy if exists fva_tenant on public.facility_visit_authorizations;create policy fva_tenant on public.facility_visit_authorizations for all to authenticated using(tenant_id=public.current_tenant_id()) with check(tenant_id=public.current_tenant_id());
drop policy if exists permits_tenant on public.entry_permits;create policy permits_tenant on public.entry_permits for all to authenticated using(tenant_id=public.current_tenant_id()) with check(tenant_id=public.current_tenant_id());
drop policy if exists employees_tenant on public.employees;create policy employees_tenant on public.employees for all to authenticated using(tenant_id=public.current_tenant_id()) with check(tenant_id=public.current_tenant_id());
commit;
